import * as path from "path"
import { parseFrontmatter } from "../../repertoire/tasks/parser"
import { emitNervesEvent } from "../../nerves/runtime"

export type HabitStatus = "active" | "paused"

export interface HabitFile {
  name: string
  title: string
  cadence: string | null
  status: HabitStatus
  lastRun: string | null
  created: string | null
  body: string
}

function isHabitStatus(value: string): value is HabitStatus {
  return value === "active" || value === "paused"
}

function extractFrontmatterAndBody(content: string): { frontmatter: Record<string, unknown>; body: string } | null {
  const lines = content.split(/\r?\n/)
  if (lines[0]?.trim() !== "---") {
    return null
  }

  const closing = lines.findIndex((line, index) => index > 0 && line.trim() === "---")
  if (closing === -1) {
    return null
  }

  const rawFrontmatter = lines.slice(1, closing).join("\n")
  const body = lines.slice(closing + 1).join("\n").trim()
  return { frontmatter: parseFrontmatter(rawFrontmatter), body }
}

export function parseHabitFile(content: string, filePath: string): HabitFile {
  emitNervesEvent({
    event: "daemon.habit_parse",
    component: "daemon",
    message: "parsing habit file",
    meta: { filePath },
  })

  const stem = path.basename(filePath, ".md")
  const parsed = extractFrontmatterAndBody(content)

  if (!parsed) {
    return {
      name: stem,
      title: stem,
      cadence: null,
      status: "active",
      lastRun: null,
      created: null,
      body: content.trim(),
    }
  }

  const { frontmatter, body } = parsed

  const rawTitle = frontmatter.title
  const title = typeof rawTitle === "string" && rawTitle.length > 0 ? rawTitle : stem

  const rawCadence = frontmatter.cadence
  const cadence = typeof rawCadence === "string" && rawCadence.length > 0 ? rawCadence : null

  const rawStatus = frontmatter.status
  const status: HabitStatus =
    typeof rawStatus === "string" && isHabitStatus(rawStatus) ? rawStatus : "active"

  const rawLastRun = frontmatter.lastRun
  const lastRun = typeof rawLastRun === "string" && rawLastRun.length > 0 ? rawLastRun : null

  const rawCreated = frontmatter.created
  const created = typeof rawCreated === "string" && rawCreated.length > 0 ? rawCreated : null

  return {
    name: stem,
    title,
    cadence,
    status,
    lastRun,
    created,
    body,
  }
}

function formatFrontmatterValue(value: unknown): string {
  if (value === null || value === undefined) return "null"
  return String(value)
}

export function renderHabitFile(frontmatter: Record<string, unknown>, body: string): string {
  emitNervesEvent({
    event: "daemon.habit_render",
    component: "daemon",
    message: "rendering habit file",
    meta: {},
  })

  const lines: string[] = ["---"]

  for (const key of Object.keys(frontmatter)) {
    lines.push(`${key}: ${formatFrontmatterValue(frontmatter[key])}`)
  }

  lines.push("---")
  lines.push("")
  lines.push(body.trim())
  lines.push("")
  return lines.join("\n")
}

**Pi-mono's coding agent (@mariozechner/pi-coding-agent) uses a **TypeScript-based extension system** where extensions are full TypeScript modules running in the same process as the agent, enabling customization via event hooks, tools, commands, UI components, and more.[1][2][5][7]**

### Core Architecture
Pi-mono is a **monorepo toolkit** with layered packages for building AI agents:
- **pi-ai**: LLM provider abstraction (supports 15+ providers like OpenAI, Ollama).[4][8]
- **pi-agent-core**: Reusable agent runtime with file tools, session persistence, context compaction.[2][4].
- **pi-coding-agent**: Minimal terminal harness that extends via **extensions, skills, prompts, themes**—not a monolithic app.[1][2][7].
- **pi-tui**: Terminal UI for CLI interfaces, supporting custom components like spinners, progress bars, file pickers.[3][4].
- Supporting: Web UI, pods for infrastructure.[2][8].

Extensions load from `~/.pi/agent/extensions/*.ts` (or npm/git/local packages) with **hot reloading** for live development—the agent can write, test, and iterate on its own extensions.[1][3][5].

### Extension API (TypeScript Interface)
Extensions receive an `ExtensionAPI` object for full control:[1]
```
interface ExtensionAPI {
  // Events
  on(event: string, handler: ExtensionHandler): void;
  events: EventBus;  // Shared pub/sub (e.g., emit/listen "task:complete")

  // Tools & Commands
  registerTool(tool: ToolDefinition): void;
  registerCommand(name: string, options: RegisteredCommand): void;

  // UI/Messaging
  sendMessage(message: CustomMessage, options?: MessageOptions): void;
  sendUserMessage(content: string | Content[], options?: MessageOptions): void;

  // State
  appendEntry(customType: string, data?: unknown): void;
  setSessionName(name: string): void;
  setLabel(entryId: string, label: string): void;

  // Models/Tools
  setModel(model: Model): Promise<boolean>;
  setActiveTools(toolNames: string[]): void;
  getActiveTools(): string[];
}
```
**Example extension**:
```typescript
// ~/.pi/agent/extensions/my-extension.ts
import type { ExtensionAPI } from "@mariozechner/pi-coding-agent";
export default function (pi: ExtensionAPI) {
  pi.on("session_start", async (event, ctx) => {
    console.log("Session started");
  });
  pi.registerTool({ /* tool def */ });
  pi.events.on("task:complete", (data) => console.log(data));
}
```

### Key Features
- **25+ hook points**: Intercept commands, block ops, add sub-agents, custom status bars, themes.[5].
- **Composable**: Stack extensions (e.g., one for UI widgets, one for tools).[5].
- **Package ecosystem**: Install via npm/git/local (`pi install <pkg>`); includes skills/themes/extensions.[5][6].
- **TUI Flexibility**: Render dashboards, Doom (proof-of-concept).[3].
- **Embeddable SDK**: Full TypeScript API for custom apps/products.[5].

This design prioritizes **modularity**—adapt the agent without forking core code.[2][7]. For setup: `npm install @mariozechner/pi-coding-agent` and point to `~/.pi/agent/extensions`.[1][4].
